  "noticeReopen": "Notificare despre stocare",
  "noticeLabel": "Notificare despre stocarea browserului",
  "noticeText": "Cook folosește stocarea browserului pentru funcțiile de gătit și de conectare pe care le folosești. Nu se adaugă stocare pentru publicitate sau analiză.",
  "noticeClose": "Închide notificarea despre stocare",
  "privDraftLabel": "Ciornă — actualizată la 28 octombrie 2026.",
  "privDraft": "Funcțiile de cont sunt în curs de testare. Datele despre operator și servicii de mai jos trebuie completate înainte de lansarea publică.",
  "privWho1": "Cook este operat de [denumirea legală și adresa poștală a operatorului]. Pentru întrebări și cereri privind confidențialitatea, scrie la [adresa de e-mail pentru confidențialitate]. Aceste date trebuie completate înainte de deschiderea înregistrării.",
  "privWhat1": "Când îți creezi un cont, folosim adresa ta de e-mail, un identificator de cont, înregistrări de autentificare cu parolă și starea verificării pentru a-ți oferi și proteja contul. Parolele sunt gestionate de furnizorul de autentificare sub formă de hash-uri sigure; Cook nu stochează parole lizibile. Stocăm amenajarea bucătăriei, limba aleasă, tema și unitățile de măsură pentru a-ți restabili setările pe toate dispozitivele. Pentru un cont sunt necesare o adresă de e-mail și o parolă; poți consulta rețete și fără cont.",
  "privWhat2": "Prelucrarea contului și a setărilor este necesară pentru a furniza serviciul de cont pe care îl soliciți (articolul 6 alineatul (1) litera (b) din RGPD). Înregistrări limitate de securitate și de prevenire a abuzurilor pot fi prelucrate în temeiul intereselor legitime (articolul 6 alineatul (1) litera (f)), în măsura necesară și după o evaluare a echilibrului. E-mailurile de verificare și de resetare a parolei sunt mesaje de serviciu, nu marketing. Funcția de cont nu adaugă publicitate sau analiză.",
  "privStorage1": "Cook folosește sessionStorage pentru a-ți păstra bucătăria, progresul la gătit și alegerile între paginile din aceeași filă. Când ești conectat, conține și sesiunea ta de autentificare. Browserul le șterge de obicei la sfârșitul sesiunii filei, dar restaurarea sesiunii din browser le poate păstra. Deconectarea șterge datele Cook din filă. Închiderea notificării despre stocare este reținută doar în acea filă. Scripturile proprii Cook nu setează cookie-uri. Furnizorii tăi de găzduire sau de servicii pot avea propriile prelucrări de securitate, care trebuie documentate înainte de lansare.",
  "privStorage2": "OK și butonul de închidere al notificării despre stocare doar închid notificarea. Ele nu autorizează analiză, publicitate sau altă urmărire opțională. Orice stocare neesențială viitoare va necesita o alegere separată înainte de a începe, cu refuz și retragere la fel de ușoare.",
  "privOther1": "Funcția vocală actuală a listei de rețete cere de la country.is o țară aproximativă pe baza adresei tale IP, pentru a alege limba de recunoaștere vocală. Dacă folosești recunoașterea prin microfon, browserul poate trimite sunetul furnizorului său de recunoaștere vocală. Poți și să tastezi ingredientele. Acești furnizori, politicile lor și temeiul legal al acestor funcții trebuie verificate înainte de lansarea publică.",
  "privProviders1": "Furnizor de conturi planificat: Supabase (PostgreSQL și autentificare gestionate), cu o regiune de bază de date selectată în UE. Furnizor de e-mail: [furnizor]. Găzduire site: [furnizor]. Operatorul trebuie să confirme furnizorii efectivi, acordurile de prelucrare, subprocesatorii, locațiile jurnalelor și orice transfer în afara SEE. O regiune de bază de date în UE nu exclude în sine transferurile internaționale. După caz, indică decizia de adecvare sau garanțiile contractuale aplicabile și cum se poate obține o copie.",
  "privRetention1": "Setările contului sunt păstrate cât timp contul tău este activ. Poți cere ștergerea prin contactul pentru confidențialitate de mai sus. Înainte de lansare, operatorul trebuie să stabilească procedura de răspuns la cererile de ștergere, expirarea conturilor neverificate și perioadele de păstrare a jurnalelor de securitate și a copiilor de rezervă. Datele șterse pot rămâne în copii de rezervă cu acces restricționat până la sfârșitul perioadei de păstrare documentate.",
  "privRights1": "În funcție de condițiile aplicabile, poți solicita accesul, rectificarea, ștergerea, restricționarea sau portabilitatea ori te poți opune prelucrării bazate pe interesul legitim. Contactează operatorul de mai sus; cererile primesc de regulă răspuns în termen de o lună, iar orice prelungire legală este explicată. Poți depune o plângere la autoritatea de supraveghere, inclusiv la NAIH din Ungaria, pe naih.hu. Cook nu folosește setările contului pentru decizii automate cu efecte juridice sau efecte similare semnificative.",
