  "Bring to a boil … Rest, covered": "Adu la fierbere … Lasă-l acoperit",
  "Onion into the pan … Taste and finish": "Ceapa în tigaie … Gustă și ajustează",
  "see Homemade Mayonnaise": "vezi Maioneză de casă",
  "Make the mayonnaise": "Fă maioneza",
  "Make the mayonnaise from the Homemade Mayonnaise recipe (about 2 tbsp per person is needed).": "Fă maioneza după rețeta Maioneză de casă (îți trebuie cam 2 linguri de persoană).",
  "Thick mayonnaise": "Maioneză groasă",
  "Wash the lettuce": "Spală salata",
  "Separate the romaine into leaves and wash them well in a colander.": "Desface salata romană în frunze și spală-le bine într-o strecurătoare.",
  "Dry the lettuce": "Usucă salata",
