  "Even thickness": "Grosime egală",
  "Season the chicken": "Condimentează puiul",
  "Rub it well in a bowl with salt, a little black pepper and some oil.": "Într-un castron, freacă-l bine cu sare, puțin piper negru și ulei.",
  "Evenly coated": "Acoperit uniform",
