  "Fry the first side.": "Prăjește prima parte.",
  "Golden underneath": "Auriu dedesubt",
  "Flip": "Întoarce",
  "Turn the chicken over.": "Întoarce puiul.",
  "Flipped": "Întors",
  "Fry the second side.": "Prăjește a doua parte.",
  "Check doneness": "Verifică dacă e gata",
  "Cut the thickest piece in half: it must be white all the way through.": "Taie în două cea mai groasă bucată: trebuie să fie albă complet.",
  "White throughout": "Alb complet",
  "Let it rest": "Lasă să se odihnească",
  "Take it out and let it rest.": "Scoate-l și lasă-l să se odihnească.",
  "Dice it into 1 to 2 cm cubes.": "Taie-l cubulețe de 1–2 cm.",
  "Cubes": "Cubulețe",
  "Grate the parmesan": "Rade parmezanul",
  "Grate the parmesan (skip if already grated).": "Rade parmezanul (sari peste dacă e deja ras).",
  "Add the lettuce. Scatter the chicken cubes, the parmesan and the croutons on it. Sprinkle a little Worcestershire sauce and add some mayonnaise on top.": "Adaugă salata. Pune deasupra cubulețele de pui, parmezanul și crutoanele. Stropește cu puțin sos Worcestershire și pune deasupra puțină maioneză.",
  "Make the mayonnaise · Grate the parmesan": "Fă maioneza · Rade parmezanul",
  "Pat the chicken dry · Halve thick fillets": "Usucă puiul · Taie pieptul gros",
  "Chicken into the pan … Check doneness": "Puiul în tigaie … Verifică dacă e gata",
  "Let it rest · Dice the chicken": "Lasă să se odihnească · Taie puiul cubulețe",
  "Preheat the oven": "Încălzește cuptorul",
