  "Cut the beef": "Taie carnea de vită",
  "Cut the beef into 1.5 cm cubes.": "Taie carnea de vită cuburi de 1,5 cm.",
  "Cubed": "Cuburi",
  "Chop the onion and garlic": "Toacă ceapa și usturoiul",
  "Finely chop the onion; crush the garlic.": "Toacă mărunt ceapa; zdrobește usturoiul.",
  "Melt the lard in the large pot and cook the onion until soft and golden.": "Topește untura în oala mare și călește ceapa până e moale și aurie.",
  "Turn up the heat, add the beef and stir until it has lost its red colour all over.": "Mărește focul, adaugă carnea de vită și amestecă până nu mai e roșie pe nicio parte.",
  "No red left": "Nu mai e roșie",
  "Paprika off the heat": "Boia departe de foc",
  "Pull the pot off the heat. Stir in the paprika, the crushed caraway and the garlic, then add a splash of water at once: paprika burns quickly and turns bitter.": "Ia oala de pe foc. Amestecă boiaua, chimenul zdrobit și usturoiul, apoi adaugă imediat puțină apă – boiaua se arde repede și devine amară.",
  "Red and fragrant": "Roșu și aromat",
  "Stew the beef": "Fierbe încet carnea",
  "Add the salt, the pepper and enough water to just cover the meat. Cover and simmer gently, adding a little water when it gets low.": "Adaugă sare, piper și apă cât să acopere carnea. Acoperă și fierbe încet, adăugând puțină apă dacă scade.",
  "Beef nearly tender": "Carnea aproape fragedă",
  "Peel the carrot, parsley root, celery root and potatoes. Cut the roots into small cubes and the potatoes into 1.5 cm cubes; chop the tomato and pepper (and the chili).": "Curăță morcovul, rădăcina de pătrunjel, țelina și cartofii. Taie rădăcinoasele cubulețe mici și cartofii cuburi de 1,5 cm; toacă roșia și ardeiul (și ardeiul iute).",
  "Roots, tomato and pepper": "Rădăcinoase, roșie și ardei",
  "Add the carrot, parsley root, celery root, tomato, pepper (and chili) with the rest of the water. Bring back to a simmer.": "Adaugă morcovul, rădăcina de pătrunjel, țelina, roșia, ardeiul (și ardeiul iute) cu restul de apă. Adu din nou la fierbere ușoară.",
  "Roots softening": "Rădăcinoasele se înmoaie",
  "Make the csipetke dough": "Fă aluatul de csipetke",
  "Knead the flour, the egg and a pinch of salt into a firm dough. Add a drop of water if it crumbles.": "Frământă făina, oul și un praf de sare într-un aluat tare. Adaugă o picătură de apă dacă se fărâmițează.",
  "Firm, smooth dough": "Aluat tare, neted",
  "Pinch the csipetke": "Ciupește csipetke",
  "Flatten the dough thinly between your palms and pinch off pea-sized pieces onto a floured plate.": "Turtește subțire aluatul între palme și ciupește din el bucățele cât un bob de mazăre pe o farfurie cu făină.",
  "Small pieces on the plate": "Bucățele pe farfurie",
  "Potatoes in": "Adaugă cartofii",
  "Add the potatoes and simmer until soft.": "Adaugă cartofii și fierbe încet până sunt moi.",
  "Potatoes soft": "Cartofii moi",
  "Csipetke in": "Adaugă csipetke",
  "Drop in the csipetke and cook until they float and are soft.": "Pune csipetke în supă și fierbe-le până ies la suprafață și sunt moi.",
  "Csipetke floating, soft": "Csipetke la suprafață, moi",
  "Taste": "Gustă",
  "Turn off the heat. Taste and add salt if needed.": "Oprește focul. Gustă și adaugă sare dacă e nevoie.",
  "Ladle into bowls and serve with fresh bread.": "Servește în boluri cu pâine proaspătă.",
  "Cut the beef … Cut the vegetables": "Taie carnea de vită … Taie legumele",
