  "Chicken thigh": "Pulpă superioară de pui",
  "Pork shoulder": "Ceafă de porc",
  "1 cm pieces": "bucăți de 1 cm",
  "Whisk the flour, the egg and the salt, then whisk in the milk and the water little by little until smooth.": "Bate făina, oul și sarea, apoi încorporează treptat laptele și apa până obții un aluat neted.",
  "Finely chop the onion; chop the tomato and the pepper.": "Toacă mărunt ceapa; toacă roșia și ardeiul.",
  "Cut the meat": "Taie carnea",
  "Cut the meat into 1 cm pieces.": "Taie carnea bucăți de 1 cm.",
  "Heat the oil in the saucepan and cook the onion until soft and golden.": "Încinge uleiul în cratiță și călește ceapa până e moale și aurie.",
  "Paprika and meat": "Boia și carne",
  "Take the pan off the heat and stir in the paprika. Add the meat, the tomato, the pepper, the salt and the water.": "Ia cratița de pe foc și amestecă boiaua. Adaugă carnea, roșia, ardeiul, sarea și apa.",
  "Meat in the red sauce": "Carne în sos roșu",
  "Stew": "Fierbe încet",
  "Cover and simmer gently until the meat is tender.": "Acoperă și fierbe încet până carnea e fragedă.",
  "Meat tender": "Carnea fragedă",
  "Lift out the meat": "Scoate carnea",
  "Lift the meat out with a slotted spoon onto the board; keep the juice in the pan.": "Scoate carnea pe tocător cu o spumieră; lasă sosul în cratiță.",
  "Juice left in the pan": "Sos în cratiță",
  "Chop the meat finely and mix it with 2 tablespoons of the sour cream and a spoonful of the juice.": "Toacă mărunt carnea și amestec-o cu 2 linguri de smântână și o lingură de sos.",
  "Juicy filling": "Umplutură suculentă",
  "Heat the frying pan and wipe it with a little oil.": "Încinge tigaia și unge-o cu puțin ulei.",
  "Pour in a small ladle of batter and tilt the pan so it covers the bottom thinly. When the edge lifts (about 1 min), flip and cook 30 seconds. About 2 crêpes per person.": "Toarnă un polonic mic de aluat și înclină tigaia ca să acoperi fundul într-un strat subțire. Când marginea se desprinde (cam 1 min), întoarce și coace 30 de secunde. Cam 2 clătite de persoană.",
  "Whisk the rest of the sour cream with the flour, stir it into the juice with a splash of water and simmer 2 to 3 minutes until creamy.": "Bate restul de smântână cu făina, amestec-o în sos cu puțină apă și fierbe 2–3 minute până e cremos.",
  "Creamy, pourable": "Cremos, îmbracă lingura",
  "Put a spoonful of filling on each crêpe, fold in the sides and roll it up. Lay them side by side in the baking dish.": "Pune o lingură de umplutură pe fiecare clătită, pliază marginile și ruleaz-o. Așază-le strâns în tava de cuptor.",
  "All rolled": "Toate rulate",
  "Sauce and bake": "Toarnă sosul și coace",
  "Pour the sauce over the crêpes and bake until bubbling.": "Toarnă sosul peste clătite și coace până bolborosește.",
  "Bubbling sauce": "Sosul bolborosește",
  "Serve hot, with a spoonful of the sauce and chopped parsley on top.": "Servește fierbinte, cu o lingură de sos și pătrunjel tocat deasupra.",
  "Chop the vegetables · Cut the meat": "Taie legumele · Taie carnea",
  "Soften the onion … Lift out the meat": "Înmoaie ceapa … Scoate carnea",
  "Preheat the oven · Sauce and bake": "Încălzește cuptorul · Toarnă sosul și coace",
  "Nokedli": "Nokedli",
  "Spaetzle maker": "Răzătoare de spätzle",
  "nokedliszaggató": "nokedliszaggató",
  "Scraped off a wet board with a knife": "Răzuite cu cuțitul de pe un tocător ud",
  "cut into thigh and drumstick": "tăiate în pulpă superioară și inferioară",
  "Cut the chicken": "Porționează puiul",
  "Cut the legs at the joint into thighs and drumsticks. Pat dry and sprinkle with the salt and pepper.": "Taie pulpele la încheietură în pulpe superioare și inferioare. Șterge-le și presară sare și piper.",
  "Cut and seasoned": "Porționat și condimentat",
  "Melt the lard in the saucepan and cook the onion until soft and golden.": "Topește untura în cratiță și călește ceapa până e moale și aurie.",
  "Take the pan off the heat, stir in the paprika and add a splash of the water at once so the paprika doesn't burn.": "Ia cratița de pe foc, amestecă boiaua și adaugă imediat puțină apă, ca boiaua să nu se ardă.",
  "Add the chicken and turn it in the paprika. Add the tomato, the pepper and the rest of the water.": "Adaugă puiul și întoarce-l prin boia. Adaugă roșia, ardeiul și restul de apă.",
  "Chicken coated": "Puiul acoperit",
  "Cover and simmer gently, turning the chicken once, until it is tender and comes away from the bone.": "Acoperă și fierbe încet, întorcând puiul o dată, până e fraged și se desprinde de pe os.",
  "Tender at the bone": "Se desprinde de pe os",
  "Make the nokedli dough": "Fă aluatul de nokedli",
  "Mix the flour, the eggs, the salt and the water into a thick, sticky dough that drops slowly from the spoon. Beat until smooth.": "Amestecă făina, ouăle, sarea și apa într-un aluat gros și lipicios care cade încet de pe lingură. Bate până e neted.",
  "Thick, sticky, smooth": "Gros, lipicios, neted",
  "Let the dough rest so it becomes smooth.": "Lasă aluatul să se odihnească, ca să devină neted.",
  "Make the nokedli": "Fă nokedli",
  "Set the spaetzle maker over the boiling water, fill the box with dough and slide it back and forth. Work in 2 or 3 batches.": "Așază răzătoarea de spätzle peste apa care fierbe, umple caseta cu aluat și glisează-o înainte și înapoi. Fă asta în 2–3 tranșe.",
  "Dough all in the water": "Tot aluatul în apă",
  "Cook until they float": "Fierbe până ies la suprafață",
  "Boil until the nokedli float, then 1 more minute.": "Fierbe până nokedli ies la suprafață, apoi încă 1 minut.",
  "Drain and toss": "Scurge și unge",
  "Drain the nokedli in a colander, rinse quickly with hot water and toss with the butter or oil so they don't stick.": "Scurge nokedli într-o strecurătoare, clătește-le repede cu apă fierbinte și amestecă-le cu unt sau ulei, ca să nu se lipească.",
  "Loose, not sticky": "Desprinse, nelipicioase",
  "Whisk the sour cream and the flour smooth in a bowl.": "Bate smântâna cu făina într-un bol până e omogenă.",
  "Thicken the sauce": "Leagă sosul",
  "Lift out the chicken. Stir a ladle of the hot sauce into the sour cream mix, then stir it all into the pan. Simmer 3 minutes and put the chicken back.": "Scoate puiul. Amestecă un polonic de sos fierbinte în smântână și toarnă totul înapoi în cratiță. Fierbe 3 minute și pune puiul înapoi.",
  "Creamy, coats the spoon": "Cremos, îmbracă lingura",
  "Serve the chicken and plenty of sauce with the nokedli.": "Servește puiul cu mult sos și nokedli.",
  "Cut the chicken · Chop the vegetables": "Porționează puiul · Taie legumele",
  "Soften the onion … Thicken the sauce": "Înmoaie ceapa … Leagă sosul",
  "Make the nokedli dough · Rest the dough": "Fă aluatul de nokedli · Lasă aluatul să stea",
  "Boil the water … Cook until they float": "Fierbe apa … Fierbe până ies la suprafață",
  "Wet the chopping board and spread some dough near its edge. Hold it over the pot and scrape thin strips into the boiling water with a wet knife, dipping the knife in the water as you go. Work in batches.": "Udă tocătorul și întinde puțin aluat lângă margine. Ține-l deasupra oalei și răzuiește fâșii subțiri în apa care fierbe cu un cuțit ud, înmuind cuțitul în apă pe parcurs. Fă asta în mai multe tranșe.",
  "Sausage": "Cârnat",
