  "1 cm rings": "rondele de 1 cm",
  "Slice the onion": "Feliază ceapa",
  "Halve the onion and slice it thinly.": "Taie ceapa în jumătate și feliaz-o subțire.",
  "Cut the peppers": "Taie ardeii",
  "Remove the stems and seeds and cut the peppers into 1 cm rings.": "Scoate codițele și semințele și taie ardeii rondele de 1 cm.",
  "Cut into rings": "Rondele",
  "Cut the tomatoes": "Taie roșiile",
  "Cut the tomatoes into chunks.": "Taie roșiile bucăți.",
  "Chunks": "Bucăți",
  "Heat the oil in the large frying pan and cook the onion until soft and glassy.": "Încinge uleiul în tigaia mare și călește ceapa până e moale și sticloasă.",
  "Soft, glassy": "Moale, sticloasă",
  "Peppers in": "Adaugă ardeii",
  "Take the pan off the heat for a moment, stir in the paprika, then add the peppers. Cook, stirring now and then, until they soften and lose their bright colour.": "Ia o clipă tigaia de pe foc, amestecă boiaua, apoi adaugă ardeii. Gătește, amestecând din când în când, până se înmoaie și își pierd culoarea vie.",
  "Peppers soft": "Ardeii moi",
  "Add the tomatoes, the salt and the sugar. Simmer uncovered until the tomatoes fall apart and most of the liquid is gone.": "Adaugă roșiile, sarea și zahărul. Fierbe fără capac până roșiile se destramă și cea mai mare parte din lichid s-a evaporat.",
  "Thick, saucy": "Gros și onctuos",
  "Serve hot with fresh bread (or rice).": "Servește fierbinte cu pâine proaspătă (sau orez).",
  "Slice the onion … Cut the tomatoes": "Feliază ceapa … Taie roșiile",
  "Soften the onion … Tomatoes in": "Înmoaie ceapa … Roșiile în oală",
