  "Beaten": "Bătute",
  "Pour the eggs over the lecsó and stir gently until they have just set.": "Toarnă ouăle peste lecsó și amestecă ușor până abia s-au închegat.",
  "Eggs just set": "Ouăle abia închegate",
  "Soften the onion … Eggs in": "Înmoaie ceapa … Ouăle în forme",
  "Slice the sausage": "Taie cârnatul",
  "Slice the sausage into rounds.": "Taie cârnatul felii.",
  "Sausage in": "Adaugă cârnatul",
  "Add the sausage and fry for 2 minutes so it releases its red fat.": "Adaugă cârnatul și prăjește-l 2 minute, ca să-și lase grăsimea roșie.",
  "Red fat in the pan": "Grăsime roșie în tigaie",
