  "separated": "separate",
  "Turn the oven on to 180 °C conventional (160 °C fan). Line the baking tray with baking paper.": "Pornește cuptorul la 180 °C, sus-jos (160 °C cu ventilație). Tapetează tava cu hârtie de copt.",
  "Oven on, tray lined": "Cuptor pornit, tavă tapetată",
  "Soak the raisins": "Înmoaie stafidele",
  "Put the raisins in a small bowl and pour half the rum over them (or a little warm water).": "Pune stafidele într-un bol mic și toarnă peste ele jumătate din rom (sau puțină apă călduță).",
  "Soaking": "La înmuiat",
  "Separate the eggs": "Separă ouăle",
  "Separate the eggs for the sponge: whites into a clean bowl, yolks into another.": "Separă ouăle pentru pandișpan: albușurile într-un bol curat, gălbenușurile în altul.",
  "Separated": "Separate",
  "Whisk the whites": "Bate albușurile",
  "Whisk the whites to soft peaks, then add half the sugar a little at a time and whisk until stiff and glossy.": "Bate albușurile spumă moale, apoi adaugă treptat jumătate din zahăr și bate până obții o spumă fermă și lucioasă.",
  "Stiff, glossy peaks": "Spumă fermă, lucioasă",
  "Yolks in": "Adaugă gălbenușurile",
  "Beat the yolks with the rest of the sugar until pale, then fold them gently into the whites.": "Bate gălbenușurile cu restul de zahăr până se albesc, apoi încorporează-le ușor în albușuri.",
  "Light and airy": "Ușor și aerat",
  "Fold in the flour": "Încorporează făina",
  "Mix the flour with the baking powder and fold it in gently in two goes.": "Amestecă făina cu praful de copt și încorporeaz-o ușor în două tranșe.",
  "Walnut and cocoa": "Nucă și cacao",
  "Divide the batter in two bowls. Fold the ground walnuts into one and the cocoa into the other.": "Împarte aluatul în două boluri. Încorporează nucile măcinate într-unul și cacaoa în celălalt.",
  "Two batters": "Două aluaturi",
  "Spread on the tray": "Întinde în tavă",
  "Fold a ridge in the middle of the baking paper and spread the walnut batter on one half, the cocoa batter on the other, about 1 cm thick.": "Fă o cută la mijlocul hârtiei de copt și întinde aluatul cu nucă pe o jumătate și pe cel cu cacao pe cealaltă, de cam 1 cm grosime.",
  "Evenly spread": "Întins uniform",
  "Bake the sponge": "Coace pandișpanul",
  "Bake until springy and a toothpick comes out clean.": "Coace până pandișpanul revine la atingere și o scobitoare iese curată.",
  "Springy, toothpick clean": "Elastic, scobitoare curată",
  "Cool the sponge": "Răcește pandișpanul",
  "Let the sponge cool on the rack.": "Lasă pandișpanul să se răcească pe grătar.",
  "Custard base": "Baza cremei",
  "Whisk the yolks, the sugar and the flour smooth with a few spoons of the milk. Heat the rest of the milk in the saucepan until it steams.": "Bate gălbenușurile, zahărul și făina cu câteva linguri de lapte până e omogen. Încălzește restul laptelui în cratiță până scoate abur.",
  "Smooth base, milk steaming": "Bază omogenă, lapte aburind",
  "Cook the custard": "Fierbe crema",
  "Pour the hot milk onto the yolks while whisking, pour it all back into the pan and cook on low, whisking all the time, until thick. Stir in the vanilla.": "Toarnă laptele fierbinte peste gălbenușuri, bătând, pune totul înapoi în cratiță și fierbe la foc mic, bătând continuu, până se îngroașă. Amestecă vanilia.",
  "Thick, coats the whisk": "Groasă, îmbracă telul",
  "Cool the custard": "Răcește crema",
  "Pour into a bowl, press cling film onto the surface and let it cool.": "Pune-o într-un bol, așază folie alimentară direct pe suprafață și las-o să se răcească.",
  "Cool, no skin": "Rece, fără pojghiță",
  "Make the syrup": "Fă siropul",
  "Boil the water and the sugar with the lemon zest for 2 minutes. Take off the heat and add the rest of the rum.": "Fierbe apa și zahărul cu coaja de lămâie 2 minute. Ia de pe foc și adaugă restul de rom.",
  "Syrupy": "Siropos",
  "Chop the walnuts": "Toacă nucile",
  "Roughly chop the walnuts for the layers.": "Toacă grob nucile pentru straturi.",
  "Tear the sponges into rough pieces. In a deep dish, layer the walnut sponge, half the syrup, half the custard, half the raisins and walnuts; then the cocoa sponge, the rest of the syrup, raisins and walnuts, and finish with the custard.": "Rupe pandișpanurile în bucăți mari. Într-un vas adânc, pune straturi de pandișpan cu nucă, jumătate din sirop, jumătate din cremă, jumătate din stafide și nuci; apoi pandișpanul cu cacao, restul de sirop, stafide și nuci, și termină cu crema.",
  "Cover and chill for at least 4 hours; overnight is best.": "Acoperă și dă la rece cel puțin 4 ore; ideal peste noapte.",
  "Set and cold": "Închegat și rece",
