  "Heat the cream for the sauce until it steams, take it off the heat and stir in the chocolate until smooth.": "Încălzește smântâna pentru sos până scoate abur, ia de pe foc și amestecă ciocolata până e omogenă.",
  "Smooth, glossy": "Omogen și lucios",
